import math
from collections.abc import Callable
from dataclasses import dataclass

from torch import Tensor

from src.mythosmini.benchmarks.runner import BenchmarkScores
from src.mythosmini.config import SLERP_MAX_GENERATIONS, SLERP_T_SWEEP, SLERP_TOP_K
from src.mythosmini.merging.slerp import slerp_state_dicts

STALL_GENERATIONS = 3
SHARED_STEP_SKIP_RATIO = 0.5


@dataclass
class MergeCandidate:
    name: str
    state: dict[str, Tensor]
    steps: frozenset[int]
    scores: BenchmarkScores


Evaluator = Callable[[str, dict[str, Tensor]], BenchmarkScores]


def improves_any_category(child: BenchmarkScores, best: BenchmarkScores) -> bool:
    return child.blimp > best.blimp or child.arc > best.arc or child.wiki_ppl < best.wiki_ppl


def category_best(candidates: list[MergeCandidate]) -> BenchmarkScores:
    return BenchmarkScores(
        wiki_ppl=min(candidate.scores.wiki_ppl for candidate in candidates),
        blimp=max(candidate.scores.blimp for candidate in candidates),
        arc=max(candidate.scores.arc for candidate in candidates),
    )


def normalized_averages(candidates: list[MergeCandidate]) -> list[float]:
    blimps = [candidate.scores.blimp for candidate in candidates]
    arcs = [candidate.scores.arc for candidate in candidates]
    wiki_logs = [-math.log(max(candidate.scores.wiki_ppl, 1e-9)) for candidate in candidates]

    def normalize(values: list[float]) -> list[float]:
        low, high = min(values), max(values)
        if high == low:
            return [0.5] * len(values)
        return [(value - low) / (high - low) for value in values]

    columns = [normalize(blimps), normalize(arcs), normalize(wiki_logs)]
    return [sum(column[index] for column in columns) / 3.0 for index in range(len(candidates))]


def select_top(candidates: list[MergeCandidate], keep: int) -> list[MergeCandidate]:
    averages = normalized_averages(candidates)
    order = sorted(range(len(candidates)), key=lambda index: averages[index], reverse=True)
    return [candidates[index] for index in order[:keep]]


def shares_too_many_steps(a: MergeCandidate, b: MergeCandidate) -> bool:
    if not a.steps or not b.steps:
        return False
    highest_a, highest_b = max(a.steps), max(b.steps)
    if highest_a == 0 or highest_b == 0:
        return False
    return min(highest_a, highest_b) / max(highest_a, highest_b) > SHARED_STEP_SKIP_RATIO


def merge_pair(
    a: MergeCandidate, b: MergeCandidate, t: float, generation: int, evaluate: Evaluator
) -> MergeCandidate:
    name = f"gen{generation}_{a.name}+{b.name}@t{t:.2f}"
    state = slerp_state_dicts(a.state, b.state, t)
    scores = evaluate(name, state)
    return MergeCandidate(name=name, state=state, steps=a.steps | b.steps, scores=scores)


def build_generation(
    parents: list[MergeCandidate], generation: int, evaluate: Evaluator
) -> list[MergeCandidate]:
    children: list[MergeCandidate] = []
    for first_index in range(len(parents)):
        for second_index in range(first_index + 1, len(parents)):
            first, second = parents[first_index], parents[second_index]
            if generation == 0 and shares_too_many_steps(first, second):
                continue
            for t in SLERP_T_SWEEP:
                children.append(merge_pair(first, second, t, generation, evaluate))
    return children


def run_tournament(
    seeds: list[MergeCandidate],
    evaluate: Evaluator,
    log: Callable[[str], None],
) -> MergeCandidate:
    if not seeds:
        raise ValueError("tournament needs at least one seed candidate")
    population = select_top(seeds, SLERP_TOP_K)
    best_average = max(normalized_averages(population))
    stalled = 0
    for generation in range(SLERP_MAX_GENERATIONS):
        if len(population) < 2:
            log(f"tournament stopped: single candidate after generation {generation}")
            break
        previous_best = category_best(population)
        children = build_generation(population, generation, evaluate)
        if not children:
            log(f"tournament stopped: no eligible pairs in generation {generation}")
            break
        if not any(improves_any_category(child.scores, previous_best) for child in children):
            log(f"tournament stopped: generation {generation} children worse in all categories")
            break
        population = select_top(population + children, SLERP_TOP_K)
        current_best = max(normalized_averages(population))
        stalled = stalled + 1 if current_best <= best_average else 0
        best_average = max(best_average, current_best)
        log(f"generation {generation}: population {len(population)}, stalled {stalled}")
        if stalled >= STALL_GENERATIONS:
            log("tournament stopped: no improvement for three generations")
            break
    return select_top(population, 1)[0]
